23	json rpc(int id, std::string method, json params = json::object())
24	{
25	    return {{"jsonrpc", "2.0"}, {"id", id}, {"method", std::move(method)}, {"params", std::move(params)}};
26	}
27	struct Harness
28	{
29	    JusPrinTest::McpDirectory directory;
30	    Workspace::FakeWorkspace workspace{fixture()};
31	    Agent::ToolExecutionCoordinator coordinator{workspace};
32	    std::unique_ptr<Mcp::McpRuntime> runtime;
33	    std::mutex mutex;
34	    std::vector<json> output;
35	    std::vector<std::string> diagnostics;
36	    Mcp::Bridge::Server bridge{{directory.path(), {}, std::chrono::milliseconds(200)},
37	        [this](Mcp::Bridge::Delivery value) { std::lock_guard<std::mutex> lock(mutex); output.push_back(std::move(value.message)); },
38	        [this](std::string value) { std::lock_guard<std::mutex> lock(mutex); diagnostics.push_back(std::move(value)); }};
39	    void start() { runtime = std::make_unique<Mcp::McpRuntime>(workspace, coordinator, directory.path()); }
40	    void pump() { if (runtime) runtime->poll(); coordinator.pump(); }
41	    void send(json message) { bridge.submit(message.dump()); }
42	    std::vector<json> messages() { std::lock_guard<std::mutex> lock(mutex); return output; }
43	    bool has(const json& id) {
44	        for (const auto& message : messages()) if (message.is_object() && message.value("id", json()) == id) return true;
45	        return false;
46	    }
47	    json wait(const json& id) {
48	        REQUIRE(JusPrinTest::wait_for([&] { return has(id); }, [&] { pump(); }));
49	        for (const auto& message : messages()) if (message.is_object() && message.value("id", json()) == id) return message;
50	        throw std::logic_error("Missing test response");
51	    }
52	    void initialize(std::string version = "2025-06-18") {
53	        send(rpc(0, "initialize", {{"protocolVersion", version}, {"capabilities", json::object()},
54	                                 {"clientInfo", {{"name", "bridge-tests"}, {"version", "1"}}}}));
55	        CHECK(wait(0)["result"]["protocolVersion"] == version);
56	        send({{"jsonrpc", "2.0"}, {"method", "notifications/initialized"}});
57	    }
58	    json settings_patch(int id, bool modern = false) {
59	        const auto snapshot = workspace.snapshot();
60	        auto call = rpc(id, "tools/call", {{"name", "settings_apply_patch"},
61	            {"arguments", {{"scope", "process"}, {"expectedSessionId", std::to_string(snapshot.session.value())}, {"expectedRevision", snapshot.revision},
62	                           {"changes", {{"wall_loops", "4"}}}}},
63	            {"_meta", {{"progressToken", id}}}});
64	        if (modern) {
65	            call["params"]["_meta"]["io.modelcontextprotocol/protocolVersion"] = Mcp::kProtocolVersion;
66	            call["params"]["_meta"]["io.modelcontextprotocol/clientCapabilities"] = json::object();
67	        }
68	        return call;
69	    }
70	};
71	}
