73	TEST_CASE("MCP bridge offline legacy catalog is projected for each negotiated version", "[mcp][bridge]")
74	{
75	    Harness h;
76	    const std::string version = GENERATE("2025-03-26", "2025-06-18", "2025-11-25");
77	    h.initialize(version);
78	    h.send(rpc(1, "tools/list"));
79	    const auto listed = h.wait(1)["result"];
80	    // Pages hold 25 tools; the catalog now has more.
81	    CHECK(listed["tools"].size() == 25);
82	    CHECK(listed["nextCursor"] == "jusprin-v1:25");
83	    CHECK_FALSE(listed.contains("ttlMs")); CHECK_FALSE(listed.contains("cacheScope"));
84	    CHECK_FALSE(listed.contains("resultType"));
