107	void HttpExchange::consume(std::string_view bytes)
108	{
109	    m_body.append(bytes);
110	    if (m_body.size() + m_event.size() > 256 * 1024) { fail("MCP response exceeds the limit."); return; }
111	    if (!m_streaming) return;
112	    for (auto end = m_body.find('\n'); end != std::string::npos; end = m_body.find('\n')) {
113	        std::string line = m_body.substr(0, end);
114	        m_body.erase(0, end + 1);
115	        if (!line.empty() && line.back() == '\r') line.pop_back();
116	        if (line.empty() && !m_event.empty()) {
117	            const auto event = std::move(m_event); m_event.clear();
118	            deliver(event);
119	            if (m_closed) return;
120	        } else if (line.compare(0, 5, "data:") == 0) {
121	            if (!m_event.empty()) m_event += '\n';
122	            m_event += line.substr(line.size() > 5 && line[5] == ' ' ? 6 : 5);
123	        }
124	    }
125	}
126	
127	void HttpExchange::deliver(const std::string& bytes)
128	{
129	    const auto value = json::parse(bytes, nullptr, false);
130	    if (!value.is_object() || value.value("jsonrpc", json()) != "2.0") { fail("Invalid MCP response envelope."); return; }
131	    const bool terminal = value.contains("result") || value.contains("error");
132	    if (terminal) {
133	        if (value.contains("result") == value.contains("error") ||
134	            (value.contains("result") && !value["result"].is_object()) ||
135	            (value.contains("error") && (!value["error"].is_object() ||
136	                !value["error"].value("code", json()).is_number_integer() || !value["error"].value("message", json()).is_string()))) {
137	            fail("Invalid MCP result or error envelope."); return;
138	        }
139	    } else if (value.contains("id") || !value.value("method", json()).is_string() ||
140	               !value.value("params", json::object()).is_object()) {
141	        fail("Invalid MCP notification envelope."); return;
142	    }
143	    if (terminal && value.value("id", json()) != m_id) { fail("MCP response ID does not match the request."); return; }
144	    if (terminal) cancel();
145	    m_message(value, terminal);
146	}
147	
148	void HttpExchange::cancel()
149	{
150	    if (m_closed) return;
151	    m_closed = true;
152	    m_deadline.cancel();
153	    Error ignored;
154	    m_socket.shutdown(net::ip::tcp::socket::shutdown_both, ignored);
155	    m_socket.close(ignored);
156	}
157	
158	void HttpExchange::fail(const std::string& reason)
159	{
160	    if (m_closed) return;
161	    cancel();
162	    m_failure(reason);
163	}
