11	bool valid_id(const json& id) { return id.is_string() || id.is_number_integer(); }
12	bool notification(const json& message)
13	{
14	    return message.is_object() && !message.contains("id") && message.value("method", json()).is_string();
15	}
16	bool depth_valid(const std::string& bytes)
17	{
18	    unsigned depth = 0;
19	    bool quoted = false, escaped = false;
20	    for (char c : bytes) {
21	        if (quoted) {
22	            if (escaped) escaped = false;
23	            else if (c == '\\') escaped = true;
24	            else if (c == '"') quoted = false;
25	        } else if (c == '"') quoted = true;
26	        else if (c == '[' || c == '{') { if (++depth > kDepthLimit) return false; }
27	        else if ((c == ']' || c == '}') && depth) --depth;
28	    }
29	    return true;
30	}
31	json error(const json& id, int code, const std::string& text)
32	{
33	    auto result = rpc_error(id, code, text);
34	    result["id"] = id; // JSON-RPC parse errors use null when no ID can be recovered.
35	    return result;
36	}
37	// The bridge speaks for the client that started it, so a forwarded call names
38	// that client; the bridge's own liveness probe names the bridge.
39	json modern_request(std::string method, json params, json id, const json& client_info = json())
40	{
41	    params["_meta"]["io.modelcontextprotocol/protocolVersion"] = kProtocolVersion;
42	    params["_meta"]["io.modelcontextprotocol/clientCapabilities"] = json::object();
43	    params["_meta"]["io.modelcontextprotocol/clientInfo"] = client_info.is_object() ? client_info
44	        : json{{"name", "jusprin-mcp"}, {"version", mcp_build_version()}};
45	    return {{"jsonrpc", "2.0"}, {"id", std::move(id)}, {"method", std::move(method)}, {"params", std::move(params)}};
46	}
47	}
