49	struct Server::Impl
50	{
51	    struct Batch { std::size_t remaining{0}; json results = json::array(); };
52	    struct Call {
53	        json rpc;
54	        bool modern{false};
55	        std::string legacy_version;
56	        std::shared_ptr<Batch> batch;
57	        std::shared_ptr<HttpExchange> exchange;
58	        std::shared_ptr<std::atomic<bool>> cancelled = std::make_shared<std::atomic<bool>>(false);
59	        bool finished{false};
60	    };
61	    Config config;
62	    Output output;
63	    std::function<void(std::string)> diagnostic;
64	    net::io_context io;
65	    net::executor_work_guard<net::io_context::executor_type> guard{io.get_executor()};
66	    std::thread worker;
67	    std::mutex ingress_mutex;
68	    std::condition_variable ingress_ready;
69	    std::size_t queued{0};
70	    bool stopped{false}; // guarded by ingress_mutex
71	    std::string legacy_version;
72	    json client_info; // from the client's initialize: name, version, and title when it sent one
73	    bool initialized{false};
74	    std::map<std::string, std::shared_ptr<Call>> calls; // io thread only
75	
76	    Impl(Config config, Output output, std::function<void(std::string)> diagnostic)
77	        : config(std::move(config)), output(std::move(output)), diagnostic(std::move(diagnostic))
78	    {
79	        if (!this->config.url_override.empty() && !loopback_port(this->config.url_override))
80	            throw std::invalid_argument("JUSPRIN_MCP_URL must be an exact http://127.0.0.1:PORT/mcp URL");
81	        worker = std::thread([this] { io.run(); });
82	    }
83	
84	    void emit(json response, const std::shared_ptr<Batch>& batch = {})
85	    {
86	        if (!batch) { if (!response.is_null()) output({std::move(response), {}}); return; }
87	        if (!response.is_null()) batch->results.push_back(std::move(response));
88	        if (--batch->remaining == 0 && !batch->results.empty()) output({std::move(batch->results), {}});
89	    }
90	
91	    void finish(const std::shared_ptr<Call>& call, json response = nullptr)
92	    {
93	        if (call->finished) return;
94	        call->finished = true;
95	        if (response.is_null()) call->cancelled->store(true);
96	        if (call->exchange) call->exchange->cancel();
97	        call->exchange.reset();
98	        calls.erase(call->rpc["id"].dump());
99	        if (!response.is_null() && !call->modern && response.contains("result")) {
100	            auto& result = response["result"];
101	            result.erase("resultType"); result.erase("ttlMs"); result.erase("cacheScope");
102	            if (call->legacy_version == "2025-03-26") {
103	                result.erase("structuredContent");
104	                if (result.contains("tools")) for (auto& tool : result["tools"]) {
105	                    tool.erase("outputSchema"); tool.erase("title");
106	                }
107	            }
108	        }
109	        emit(std::move(response), call->batch);
110	    }
111	
112	    void offline(const std::shared_ptr<Call>& call)
113	    {
114	        const auto parsed = parse_request(wire_request(call->rpc), "http://127.0.0.1:1");
115	        if (!parsed.request) { finish(call, parsed.error.body); return; }
116	        const auto& request = *parsed.request;
117	        if (request.method == "server/discover") finish(call, discovery(request).body);
118	        else if (request.method == "tools/list") finish(call, list_tools(request).body);
119	        else finish(call, rpc_result(request.id, tool_result(tool_error("workspace_unavailable",
120	            "Open JusPrin and a project, then try again. The bridge does not launch JusPrin."), true)));
121	    }
122	
123	    void forward(const std::shared_ptr<Call>& call, unsigned short port)
124	    {
125	        call->exchange = std::make_shared<HttpExchange>(io, port, wire_request(call->rpc), config.call_timeout,
126	            [this, call](json message, bool terminal) {
127	                if (call->finished) return;
128	                if (terminal) { finish(call, std::move(message)); return; }
129	                if (message.value("method", json()) == "notifications/progress") {
130	                    const auto meta = call->rpc["params"].value("_meta", json::object());
131	                    if (!meta.contains("progressToken")) return;
132	                    message["params"]["progressToken"] = meta["progressToken"];
133	                    output({std::move(message), call->cancelled});
134	                }
135	            }, [this, call](const std::string& reason) {
136	                finish(call, rpc_result(call->rpc["id"], tool_result(tool_error("connection_lost",
137	                    "Connection to JusPrin was lost before its result arrived. The operation's outcome is unknown; inspect the workspace before retrying.",
138	                    {{"reason", reason}}), true)));
139	            });
140	        call->exchange->start();
141	    }
142	
143	    void route(const std::shared_ptr<Call>& call)
144	    {
145	        std::string url = config.url_override;
146	        if (url.empty()) {
147	            const auto record = read_discovery(config.discovery_path);
148	            if (!record) { offline(call); return; }
149	            url = record->url;
150	            if (record->app_version != mcp_build_version())
151	                diagnostic("JusPrin and jusprin-mcp versions differ; forwarding the live catalog and calls.");
152	        }
153	        const auto port = *loopback_port(url);
154	        const auto probe = modern_request("server/discover", json::object(), "bridge-liveness");
155	        call->exchange = std::make_shared<HttpExchange>(io, port, wire_request(probe), config.probe_timeout,
156	            [this, call, port](json message, bool terminal) {
157	                if (!terminal || call->finished) return;
158	                const auto result = message.value("result", json::object());
159	                const auto failure = message.value("error", json::object());
160	                const bool discovered = result.is_object() && result.value("supportedVersions", json()).is_array();
161	                const bool unsupported = failure.is_object() && failure.value("code", json()) == -32022;
162	                if (discovered || unsupported) forward(call, port);
163	                else offline(call);
164	            }, [this, call](const std::string&) { if (!call->finished) offline(call); });
165	        call->exchange->start();
166	    }
167	
168	    void dispatch(json message, std::shared_ptr<Batch> batch = {})
169	    {
170	        if (notification(message)) {
171	            if (message.value("jsonrpc", json()) != "2.0" || !message.value("params", json::object()).is_object()) return;
172	            if (message["method"] == "notifications/initialized" && !legacy_version.empty()) initialized = true;
173	            if (message["method"] == "notifications/cancelled") {
174	                const auto params = message.value("params", json::object());
175	                if (params.is_object() && valid_id(params.value("requestId", json()))) {
176	                    const auto found = calls.find(params["requestId"].dump());
177	                    if (found != calls.end()) { auto call = found->second; finish(call); }
178	                }
179	            }
180	            return;
181	        }
182	        const json id = message.is_object() && valid_id(message.value("id", json())) ? message["id"] : json();
183	        if (!message.is_object() || message.value("jsonrpc", json()) != "2.0" || id.is_null() ||
184	            !message.value("method", json()).is_string() || message.contains("result") || message.contains("error")) {
185	            emit(error(id, -32600, "Expected a JSON-RPC request with a string or integer ID."), batch); return;
186	        }
187	        auto params = message.value("params", json::object());
188	        if (!params.is_object() || !params.value("_meta", json::object()).is_object()) {
189	            emit(error(id, -32602, "Request params and metadata must be objects."), batch); return;
190	        }
191	        const std::string method = message["method"];
192	        const bool modern = params.value("_meta", json::object()).contains("io.modelcontextprotocol/protocolVersion");
193	        if (!modern && method == "initialize") {
194	            const auto info = params.value("clientInfo", json::object());
195	            if (!params.value("protocolVersion", json()).is_string() || !params.value("capabilities", json()).is_object() ||
196	                !info.is_object() || !info.value("name", json()).is_string() || !info.value("version", json()).is_string()) {
197	                emit(error(id, -32602, "initialize requires protocolVersion, capabilities, and clientInfo."), batch); return;
198	            }
199	            if (!legacy_version.empty()) { emit(error(id, -32600, "Already initialized."), batch); return; }
200	            legacy_version = params["protocolVersion"].get<std::string>();
201	            client_info = {{"name", info["name"]}, {"version", info["version"]}};
202	            if (info.value("title", json()).is_string()) client_info["title"] = info["title"];
203	            if (legacy_version != "2025-03-26" && legacy_version != "2025-06-18" && legacy_version != "2025-11-25")
204	                legacy_version = "2025-06-18";
205	            json result{{"protocolVersion", legacy_version},
206	                {"capabilities", {{"tools", {{"listChanged", false}}}}}, {"serverInfo", {{"name", "JusPrin"}, {"version", mcp_build_version()}}},
207	                {"instructions", discovery({id, "server/discover", json::object()}).body["result"]["instructions"]}};
208	            emit({{"jsonrpc", "2.0"}, {"id", id}, {"result", std::move(result)}}, batch);
209	            return;
210	        }
211	        if (!modern && method == "ping") { emit({{"jsonrpc", "2.0"}, {"id", id}, {"result", json::object()}}, batch); return; }
212	        if (!modern && method != "tools/list" && method != "tools/call") {
213	            emit(error(id, -32601, "Method not found."), batch); return;
214	        }
215	        if (!modern && !initialized) { emit(error(id, -32000, "Complete initialize first."), batch); return; }
216	        if (calls.count(id.dump())) { emit(error(id, -32600, "Request ID is already in flight."), batch); return; }
217	        if (calls.size() >= 16) { emit(error(id, -32000, "At most 16 requests may be in flight."), batch); return; }
218	        auto call = std::make_shared<Call>();
219	        call->modern = modern; call->legacy_version = legacy_version; call->batch = std::move(batch);
220	        call->rpc = modern ? std::move(message) : modern_request(method, std::move(params), id, client_info);
221	        calls.emplace(id.dump(), call);
222	        route(call);
223	    }
224	
225	    void accept(const std::string& line)
